INSERT INTO training_exercises (category,name,summary,description,benefits,target,difficulty,cues,mistakes,level_min,sort_order,image_url)
VALUES
($sd$워밍업$sd$,$sd$다이나믹 스트레칭 루틴$sd$,$sd$팔다리를 크게 움직이며 몸을 따뜻하게 데워요$sd$,$sd$운동 전에 몸을 깨우는 움직이는 스트레칭이에요. 목 돌리기, 어깨 돌리기, 팔 크게 돌리기, 허리 돌리기, 무릎 들기 순서로 위에서 아래로 내려가요. 한 동작을 10회씩 반동 없이 부드럽게 이어서 하고, 몸이 살짝 따뜻해지면 준비 완료예요.$sd$,$sd$관절이 움직일 수 있는 범위를 넓히고 근육 온도를 올려서, 첫 훈련 블록부터 몸이 가볍게 움직여요.$sd$,$sd$목·어깨·허리·고관절·무릎 전신 관절$sd$,$sd$초급$sd$,$sd$["목, 어깨, 허리, 무릎 순서로 위에서 아래로 내려가요", "한 동작에 10회씩 천천히 크게 돌려요", "반동을 쓰지 말고 부드럽게 이어서 움직여요", "숨은 참지 말고 자연스럽게 쉬어요"]$sd$::jsonb,$sd$["동작을 빠르게 휙휙 넘겨요 → 한 동작 10회를 소리 내어 세면서 천천히 해요", "숨을 참고 힘을 줘요 → 숫자를 세며 말하면 호흡이 저절로 자연스러워져요"]$sd$::jsonb,1,10,$sd$/assets/training/dynamic-stretch-routine.png$sd$),
($sd$워밍업$sd$,$sd$밴드 쉐도우 복싱$sd$,$sd$고무 밴드를 등에 걸고 팔을 쭉쭉 뻗으며 펀치 흉내를 내요$sd$,$sd$가벼운 고무 밴드를 등 뒤로 돌려 양손에 잡고 하는 쉐도우 복싱이에요. 밴드가 살짝 당기는 느낌을 이기면서 잽과 스트레이트를 천천히 끝까지 뻗어요. 밴드 저항 덕분에 어깨와 팔이 금방 따뜻해져요. 30초 움직이고 15초 쉬는 방식으로 2~3세트면 충분해요.$sd$,$sd$어깨와 팔을 안전하게 데우고, 펀치를 끝까지 뻗었다가 빠르게 되돌리는 감각을 미리 깨워요.$sd$,$sd$어깨·팔·등 상부$sd$,$sd$초급$sd$,$sd$["밴드는 등 뒤 겨드랑이 높이에 걸어요", "팔꿈치는 몸에 붙였다가 일직선으로 쭉 뻗어요", "뻗은 팔은 빠르게 턱 옆 가드로 되돌려요", "세게 말고 천천히 끝까지 뻗는 게 먼저예요"]$sd$::jsonb,$sd$["밴드가 너무 강해서 어깨가 으쓱 올라가요 → 가장 약한 밴드로 바꾸고 어깨 힘을 빼요", "팔만 뻗고 가드로 안 돌아와요 → 뻗은 길 그대로 턱 옆까지 빠르게 되돌려요"]$sd$::jsonb,1,20,$sd$/assets/training/band-shadow-boxing.png$sd$),
($sd$워밍업$sd$,$sd$아령 쉐도우 복싱$sd$,$sd$아주 가벼운 아령을 들고 천천히 펀치 연습을 해요$sd$,$sd$0.5~1kg 가벼운 무게의 아령을 양손에 하나씩 들고 하는 쉐도우 복싱이에요. 잽과 스트레이트를 평소보다 조금 느리게, 폼이 무너지지 않는 속도로 뻗어요. 30초 하고 30초 쉬기를 2~3번 반복하면 어깨가 충분히 따뜻해져요. 반드시 0.5~1kg 가벼운 무게만 쓰고, 어깨가 힘들면 아령 없이 맨손으로 해요.$sd$,$sd$어깨 지구력이 좋아지고, 펀치를 뻗은 뒤 가드로 되돌리는 힘이 길러져요.$sd$,$sd$어깨·팔·손목$sd$,$sd$초급$sd$,$sd$["아령은 0.5~1kg 가벼운 것만 들어요", "펀치는 천천히, 맨손과 똑같은 폼으로 뻗어요", "손목은 꺾이지 않게 곧게 유지해요", "어깨가 아프면 바로 내려놓고 맨손으로 바꿔요"]$sd$::jsonb,$sd$["무거운 아령을 들고 해요 → 1kg 이하로 바꾸고 폼을 지키는 데 집중해요", "팔을 휘둘러 던지듯 뻗어요 → 일직선으로 뻗고 같은 길로 되돌려요"]$sd$::jsonb,2,30,$sd$/assets/training/dumbbell-shadow-boxing.png$sd$),
($sd$워밍업$sd$,$sd$아령 샌드백 터치$sd$,$sd$가벼운 아령을 든 손으로 샌드백을 살짝살짝 갖다 대요$sd$,$sd$0.5~1kg 가벼운 무게의 아령을 들고 샌드백 앞에서 하는 워밍업이에요. 세게 치지 않고 팔을 쭉 뻗어 아령 끝이 샌드백에 살짝 닿게만 해요. 좌우 손을 번갈아 대면서 발도 조금씩 옆으로 옮겨 샌드백 주위를 돌아요. 치는 운동이 아니라 거리를 재고 어깨를 데우는 운동이에요.$sd$,$sd$샌드백과 내 팔 길이 사이의 거리 감각을 익히고, 어깨와 팔을 부드럽게 데워요.$sd$,$sd$어깨·팔·거리 감각$sd$,$sd$초급$sd$,$sd$["아령은 0.5~1kg만 사용해요", "치지 말고 뻗어서 콕 닿게만 해요", "닿는 순간에도 반대 손은 턱 옆 가드예요", "한 번 대면 발을 반 발짝 옆으로 옮겨요"]$sd$::jsonb,$sd$["샌드백을 세게 쳐요 → 소리가 안 날 만큼 살짝 대기만 해요", "팔을 뻗을 때 반대 손 가드가 내려가요 → 반대 주먹은 항상 턱 옆에 붙여 두어요"]$sd$::jsonb,3,40,$sd$/assets/training/dumbbell-bag-touch.png$sd$),
($sd$워밍업$sd$,$sd$스텝터치+가드업$sd$,$sd$옆으로 한 발씩 콩콩 옮기면서 두 손은 얼굴 옆을 지켜요$sd$,$sd$에어로빅 스텝터치에 복싱 가드를 합친 워밍업이에요. 오른쪽으로 한 발 옮기고 반대 발을 톡 붙인 다음, 다시 왼쪽으로 돌아와요. 그동안 두 주먹은 턱 옆 가드 위치에 계속 붙여 두어요. 음악이나 구령에 맞춰 30초~1분씩 리듬을 타면 돼요.$sd$,$sd$다리를 데우면서 가드를 오래 유지하는 습관을 동시에 만들어요. 리듬 감각의 기초가 돼요.$sd$,$sd$다리·어깨·리듬 감각$sd$,$sd$초급$sd$,$sd$["옆으로 한 발 옮기고 반대 발을 톡 붙여요", "주먹은 턱 옆, 팔꿈치는 몸에 붙여요", "무릎을 살짝 굽혀 통통 리듬을 타요", "시선은 정면 거울을 봐요"]$sd$::jsonb,$sd$["하다 보면 팔이 점점 내려와요 → 스스로 가드 업을 외치며 주먹을 턱 옆에 다시 붙여요", "발을 바닥에 질질 끌어요 → 발끝으로 가볍게 콩콩 옮겨요"]$sd$::jsonb,1,50,$sd$/assets/training/step-touch-guard-up.png$sd$),
($sd$워밍업$sd$,$sd$벽 잽 터치$sd$,$sd$벽에 붙인 표시를 잽으로 살짝살짝 터치해요$sd$,$sd$벽에 눈높이로 테이프 표시를 붙이고, 그 지점을 잽으로 가볍게 터치하는 연습이에요. 주먹이 벽에 톡 닿을 만큼의 거리에 서서 팔을 쭉 뻗어 표시를 정확히 맞혀요. 세게 치면 손목을 다칠 수 있으니 종이를 만지듯 살짝만 대요. 10회씩 3번 하고, 맞힌 개수를 세면 더 재미있어요.$sd$,$sd$잽을 일직선으로 정확한 지점에 뻗는 조준 감각과 팔 길이 거리 감각이 좋아져요.$sd$,$sd$어깨·팔·조준 감각$sd$,$sd$초급$sd$,$sd$["표시가 톡 닿는 거리에 서요", "팔꿈치를 펴며 일직선으로 뻗어요", "닿는 순간만 주먹을 살짝 쥐고 바로 되돌려요", "반대 손은 턱 옆에 붙여 두어요"]$sd$::jsonb,$sd$["벽을 세게 쳐요 → 소리 없이 종이 만지듯 살짝 터치만 해요", "몸이 앞으로 쏠리며 쳐요 → 발 위치를 지키고 팔 길이만큼만 뻗어요"]$sd$::jsonb,1,60,$sd$/assets/training/wall-jab-touch.png$sd$),
($sd$워밍업$sd$,$sd$사다리 스텝 트레이닝$sd$,$sd$바닥 사다리 칸을 한 칸씩 차례로 밟으며 지나가요$sd$,$sd$바닥에 놓인 줄사다리 칸을 밟으며 지나가는 워밍업이에요. 처음에는 한 칸에 한 발씩 걸어서 지나가고, 익숙해지면 한 칸에 두 발씩 빠르게 밟아요. 시선은 계속 앞을 보고 발끝으로 가볍게 통통 딛어요. 왕복 4~6번이면 다리가 기분 좋게 따뜻해져요. 사다리가 없으면 바닥에 테이프로 칸을 만들어서 하면 돼요.$sd$,$sd$발을 빠르고 정확하게 옮기는 능력과 발목의 탄력이 좋아져서 모든 풋워크의 바탕이 돼요.$sd$,$sd$발목·종아리·발 빠르기$sd$,$sd$초급$sd$,$sd$["발끝으로 가볍게 통통 밟아요", "한 칸에 한 발부터, 익숙해지면 한 칸에 두 발로 해요", "시선은 발이 아니라 앞을 봐요", "팔은 달리기처럼 가볍게 흔들어요"]$sd$::jsonb,$sd$["발만 내려다보고 걸어요 → 두세 칸 앞 바닥을 보면 발이 저절로 따라와요", "칸을 밟거나 건너뛰어요 → 속도를 줄이고 한 칸씩 정확히 밟는 것부터 해요"]$sd$::jsonb,2,70,$sd$/assets/training/ladder-step-warmup.png$sd$),
($sd$워밍업$sd$,$sd$라인 홉$sd$,$sd$바닥 선을 두 발로 좌우로 폴짝폴짝 넘어요$sd$,$sd$바닥에 그어진 선 하나를 사이에 두고 두 발을 모아 좌우로 폴짝폴짝 넘는 워밍업이에요. 발목과 무릎을 스프링처럼 써서 낮고 빠르게 뛰어요. 20초 뛰고 20초 쉬기를 3번 반복하고, 익숙해지면 앞뒤로 넘기나 한 발로 넘기로 조금씩 어렵게 만들어요. 뛰기가 힘들면 선을 밟지 않게 좌우로 빠르게 걸어서 넘어도 좋아요.$sd$,$sd$발목 탄력과 두 발의 리듬감이 좋아져서 줄넘기와 스텝이 한결 가벼워져요.$sd$,$sd$발목·종아리·리듬 감각$sd$,$sd$초급$sd$,$sd$["두 발을 모으고 낮게 폴짝폴짝 넘어요", "발목을 스프링처럼 통통 튕겨요", "무릎을 살짝 굽혀 충격을 부드럽게 받아요", "시선은 정면, 가슴은 곧게 세워요"]$sd$::jsonb,$sd$["높이 뛰어서 금방 지쳐요 → 발이 바닥에서 조금만 뜨게 낮게 뛰어요", "착지할 때 쿵 소리가 나요 → 발끝부터 살며시 내려앉게 무릎을 부드럽게 써요"]$sd$::jsonb,2,80,$sd$/assets/training/line-hop.png$sd$),
($sd$줄넘기$sd$,$sd$복서 스텝 줄넘기$sd$,$sd$줄을 돌리며 왼발 오른발을 번갈아 콩콩 바꿔 뛰어요$sd$,$sd$복서들이 가장 많이 쓰는 줄넘기 스텝이에요. 두 발을 동시에 뛰는 대신 체중을 왼발과 오른발로 번갈아 옮기면서 뛰어요. 제자리에서 달리기를 아주 작게 하는 느낌이에요. 30초~1분씩 3라운드 하고, 줄에 자꾸 걸리면 줄 없이 발 바꾸기만 먼저 연습해도 돼요.$sd$,$sd$복싱 특유의 좌우 리듬과 발 체중 옮기기를 익혀서 스텝과 펀치 연결이 자연스러워져요.$sd$,$sd$발목·종아리·심폐 지구력$sd$,$sd$초급$sd$,$sd$["체중을 왼발에서 오른발로 번갈아 옮겨요", "발은 바닥에서 살짝만 띄워요", "팔꿈치는 옆구리에 붙이고 손목으로만 줄을 돌려요", "리듬이 흔들리면 두 발 뛰기로 잠깐 돌아와요"]$sd$::jsonb,$sd$["무릎을 높이 들어 행진하듯 뛰어요 → 발끝이 바닥을 스치듯 낮게 바꿔 밟아요", "팔 전체를 크게 돌려요 → 팔꿈치를 옆구리에 붙이고 손목만 작게 돌려요"]$sd$::jsonb,2,90,$sd$/assets/training/rope-boxer-step.png$sd$),
($sd$줄넘기$sd$,$sd$줄넘기 좌우 흔들기$sd$,$sd$줄을 돌리면서 두 발을 모아 좌우로 왔다 갔다 뛰어요$sd$,$sd$스키 타는 사람처럼 두 발을 모은 채 좌우로 조금씩 이동하며 뛰는 줄넘기 변형이에요. 기본 바운스가 익숙해진 다음에 도전해요. 발을 모아 오른쪽으로 한 뼘, 왼쪽으로 한 뼘씩 움직이면서 줄은 똑같은 빠르기로 돌려요. 30초씩 3번이면 충분해요. 힘들면 줄 없이 좌우 점프만 먼저 연습해요.$sd$,$sd$뛰면서 몸을 옆으로 옮기는 감각이 생겨서 사이드 스텝과 회피 움직임의 기초가 돼요.$sd$,$sd$발목·종아리·좌우 균형$sd$,$sd$초급$sd$,$sd$["두 발을 모아 좌우로 한 뼘씩만 움직여요", "상체는 가운데 세우고 다리만 왔다 갔다 해요", "줄은 손목으로 일정한 빠르기로 돌려요", "낮게 뛰면서 리듬을 똑같이 지켜요"]$sd$::jsonb,$sd$["좌우로 너무 크게 뛰어 줄에 걸려요 → 한 뼘 거리만 작게 왔다 갔다 해요", "상체가 다리를 따라 기울어요 → 머리는 가운데 두고 발만 움직여요"]$sd$::jsonb,3,100,$sd$/assets/training/rope-side-sway.png$sd$),
($sd$기본기$sd$,$sd$거울 스탠스 체크$sd$,$sd$거울 앞에서 복싱 기본 자세를 만들고 하나하나 확인해요$sd$,$sd$거울 앞에 서서 복싱 기본 자세를 스스로 점검하는 연습이에요. 발 너비, 발 각도, 무릎 굽힘, 가드 높이, 턱 위치를 위에서 아래 순서로 하나씩 확인해요. 체크가 끝나면 자세를 완전히 풀었다가 3초 안에 다시 만들어 봐요. 5번 반복해서 언제 만들어도 같은 자세가 나오면 성공이에요.$sd$,$sd$모든 기술의 출발점인 스탠스를 스스로 점검하는 눈이 생겨서 코치가 없어도 자세가 무너지지 않아요.$sd$,$sd$전신 자세·균형$sd$,$sd$초급$sd$,$sd$["발은 어깨너비, 뒷발 뒤꿈치는 살짝 들어요", "무릎은 살짝 굽혀 스프링처럼 서요", "주먹은 턱 옆, 팔꿈치로 갈비뼈를 가려요", "턱은 살짝 당기고 눈은 정면을 봐요"]$sd$::jsonb,$sd$["두 발이 한 줄 위에 놓여 휘청거려요 → 기찻길처럼 두 줄 위에 앞발과 뒷발을 따로 놓아요", "가슴이 정면을 활짝 봐요 → 몸을 반쯤 옆으로 돌려 상대에게 보이는 면을 작게 만들어요"]$sd$::jsonb,1,110,$sd$/assets/training/mirror-stance-check.png$sd$),
($sd$기본기$sd$,$sd$가드 60초 챌린지$sd$,$sd$두 주먹을 얼굴 옆에 붙인 채 60초 동안 버텨요$sd$,$sd$가드 자세를 60초 동안 무너뜨리지 않고 유지하는 도전이에요. 스탠스를 만들고 주먹은 턱 옆, 팔꿈치는 몸통에 붙인 채 시간을 재요. 중간에 어깨가 무거워져도 팔을 내리지 말고 어깨 힘을 빼는 방법을 찾아봐요. 60초가 쉬워지면 제자리에서 살짝 리듬을 타면서 버텨 봐요.$sd$,$sd$가드를 오래 유지하는 어깨 지구력이 생기고, 지쳤을 때도 가드가 내려가지 않는 습관이 몸에 새겨져요.$sd$,$sd$어깨·팔·가드 지구력$sd$,$sd$초급$sd$,$sd$["주먹은 광대뼈 높이, 턱은 살짝 당겨요", "팔꿈치로 갈비뼈를 가려요", "어깨는 으쓱 올리지 말고 힘을 빼요", "코로 천천히 숨 쉬며 버텨요"]$sd$::jsonb,$sd$["시간이 지나며 주먹이 배꼽까지 내려와요 → 10초마다 가드를 외치며 광대 높이로 다시 올려요", "어깨에 잔뜩 힘이 들어가 금방 지쳐요 → 숨을 길게 내쉬며 어깨를 아래로 툭 떨어뜨려요"]$sd$::jsonb,1,120,$sd$/assets/training/guard-hold-challenge.png$sd$),
($sd$기본기$sd$,$sd$번호 콜 리액션$sd$,$sd$코치가 외치는 번호를 듣고 바로 그 펀치를 던져요$sd$,$sd$코치나 파트너가 1 또는 2를 외치면 듣자마자 잽(1)이나 스트레이트(2)를 던지는 반응 연습이에요. 가드 자세로 리듬을 타며 기다리다가 번호가 들리면 1초 안에 정확한 폼으로 던지고 가드로 돌아와요. 익숙해지면 1-2처럼 이어지는 번호도 섞어요. 30초씩 3라운드면 충분해요.$sd$,$sd$듣고 바로 몸이 반응하는 속도가 빨라지고, 배운 펀치를 생각 없이도 정확하게 꺼내 쓸 수 있게 돼요.$sd$,$sd$반응 속도·집중력·펀치 정확도$sd$,$sd$초급$sd$,$sd$["번호를 듣고 1초 안에 던져요", "던진 손은 나간 길 그대로 돌아와요", "기다리는 동안에도 리듬을 계속 타요", "틀려도 멈추지 말고 다음 번호에 집중해요"]$sd$::jsonb,$sd$["번호를 듣고 한참 생각한 뒤 던져요 → 속도를 늦춰도 좋으니 듣자마자 몸이 먼저 나가게 해요", "던진 뒤 손이 허리로 떨어져요 → 펀치가 나간 길로 턱 옆까지 다시 돌아와요"]$sd$::jsonb,4,130,$sd$/assets/training/number-call-reaction.png$sd$),
($sd$풋워크$sd$,$sd$앞발 피벗 턴$sd$,$sd$앞발을 축으로 삼아 몸을 빙그르르 돌려 방향을 바꿔요$sd$,$sd$앞발 발끝을 바닥에 축처럼 고정하고 뒷발을 옆으로 돌려서 몸의 방향을 바꾸는 풋워크예요. 문이 문틀에 붙은 채 열리는 것처럼 앞발은 제자리에 두고 뒷발만 90도 정도 돌아가요. 돌고 난 뒤에도 스탠스 너비와 가드가 그대로여야 해요. 좌우로 10번씩 천천히 연습해요.$sd$,$sd$정면으로만 움직이지 않고 각도를 바꾸는 능력이 생겨서 나중에 상대를 옆에서 보는 위치 싸움의 기초가 돼요.$sd$,$sd$발목·고관절·방향 전환 감각$sd$,$sd$초급$sd$,$sd$["앞발 발끝을 축으로 바닥에 붙여요", "뒷발을 빗자루로 바닥을 쓸듯 옆으로 돌려요", "도는 동안 가드는 턱 옆에 그대로 두어요", "돌고 나서 발 너비와 무릎 굽힘을 다시 확인해요"]$sd$::jsonb,$sd$["두 발이 같이 폴짝 뛰면서 돌아요 → 앞발은 못 박힌 듯 그 자리에 두고 뒷발만 돌려요", "돌고 나면 다리가 펴지고 자세가 높아져요 → 도는 내내 무릎 굽힘을 그대로 유지해요"]$sd$::jsonb,5,140,$sd$/assets/training/lead-foot-pivot.png$sd$),
($sd$풋워크$sd$,$sd$네모 박스 스텝$sd$,$sd$바닥에 네모를 그리듯 앞·옆·뒤·옆으로 스텝을 밟아요$sd$,$sd$바닥의 네모 모서리를 따라 전진, 사이드, 후진, 사이드 순서로 도는 풋워크 연습이에요. 항상 가고 싶은 방향의 발이 먼저 움직이고 반대 발이 따라와요. 두 발이 서로 만나거나 꼬이면 안 돼요. 가드를 올린 채 네모를 시계 방향으로 3바퀴, 반대 방향으로 3바퀴 돌아요.$sd$,$sd$네 방향 스텝이 하나로 이어져서 어느 쪽으로든 자세가 무너지지 않고 움직일 수 있게 돼요.$sd$,$sd$다리·균형·스텝 연결 능력$sd$,$sd$초급$sd$,$sd$["가는 방향 발이 먼저, 반대 발이 따라와요", "발 사이 간격은 항상 어깨너비를 지켜요", "네 모서리에서 잠깐 멈춰 자세를 확인해요", "가드는 내내 턱 옆에 두어요"]$sd$::jsonb,$sd$["두 발이 가까워져 깡충거리게 돼요 → 모서리마다 멈춰서 발 너비를 어깨너비로 다시 벌려요", "바닥만 내려다봐요 → 정면 거울을 보고 발은 느낌으로 움직여요"]$sd$::jsonb,5,150,$sd$/assets/training/box-step-drill.png$sd$),
($sd$풋워크$sd$,$sd$인-아웃 스텝 드릴$sd$,$sd$빠르게 한 걸음 들어갔다가 곧바로 제자리로 빠져나와요$sd$,$sd$상대에게 들어가서 치고 안전하게 빠져나오는 발을 만드는 연습이에요. 앞발부터 한 걸음 빠르게 들어가고, 곧바로 뒷발부터 밀어서 원래 자리로 돌아와요. 들어갈 때와 나올 때 모두 가드는 턱 옆에 있어야 해요. 바닥에 테이프로 출발선을 정하면 더 정확해져요. 10회씩 3세트 하고, 익숙해지면 들어갈 때 잽을 붙여요.$sd$,$sd$치고 빠지는 복싱의 기본 흐름이 발에 새겨져서 들어간 뒤에도 안전하게 돌아올 수 있어요.$sd$,$sd$다리·순발력·거리 조절 능력$sd$,$sd$초급$sd$,$sd$["들어갈 때는 앞발 먼저, 나올 때는 뒷발부터 밀어요", "크게 한 걸음, 발을 질질 끌지 않아요", "들어가서도 무릎 굽힘을 그대로 유지해요", "나온 뒤 바로 다시 들어갈 수 있는 자세로 서요"]$sd$::jsonb,$sd$["들어갔다가 천천히 걸어서 나와요 → 들어간 속도 그대로 튕기듯 빠져나와요", "들어갈 때 상체가 먼저 앞으로 쏠려요 → 발이 먼저 가고 몸이 따라가게 해요"]$sd$::jsonb,7,160,$sd$/assets/training/in-out-step-drill.png$sd$),
($sd$방어$sd$,$sd$커버업 쉘 자세$sd$,$sd$장갑으로 얼굴을 감싸고 거북이처럼 몸을 웅크려 지켜요$sd$,$sd$두 장갑을 이마와 광대에 붙이고 팔꿈치로 몸통을 가려서, 거북이 등딱지처럼 온몸을 지키는 방어 자세예요. 시선은 팔 틈 사이로 계속 앞을 봐요. 자세를 만들고 10초 유지했다가 풀고 다시 만들기를 5번 반복해요. 익숙해지면 파트너가 어깨를 가볍게 미는 동안에도 자세를 지켜 봐요.$sd$,$sd$위험한 순간에 몸을 안전하게 감싸는 최후의 방패가 생겨서 자신감 있게 방어를 배울 수 있어요.$sd$,$sd$팔·어깨·몸통 보호 자세$sd$,$sd$초급$sd$,$sd$["장갑을 이마와 광대에 딱 붙여요", "팔꿈치로 갈비뼈 앞을 가려요", "턱을 당기고 팔 틈으로 앞을 계속 봐요", "몸을 살짝 웅크려 작게 만들어요"]$sd$::jsonb,$sd$["눈을 감고 고개를 푹 숙여요 → 팔 틈으로 상대를 계속 보면서 웅크려요", "팔꿈치가 벌어져 몸통이 보여요 → 팔꿈치를 갈비뼈에 자석처럼 붙여요"]$sd$::jsonb,6,170,$sd$/assets/training/cover-up-shell.png$sd$),
($sd$방어$sd$,$sd$어깨 터치 가드 게임$sd$,$sd$친구가 어깨를 살짝 치려 하면 가드와 스텝으로 피해요$sd$,$sd$파트너와 마주 서서 서로의 어깨만 손바닥으로 살짝 터치하려고 겨루는 게임이에요. 펀치는 없고 손바닥 터치만 있어서 안전해요. 가드를 올린 채 작은 스텝으로 거리를 조절하고, 상대 손이 오면 어깨를 살짝 돌리거나 반 발짝 물러나 피해요. 30초씩 3판 하고, 터치당한 횟수가 적은 사람이 이겨요.$sd$,$sd$상대를 보면서 거리와 타이밍을 읽는 눈이 생겨요. 맞지 않는 감각을 안전하게 처음 배우는 게임이에요.$sd$,$sd$거리 감각·반응 속도·시선 유지$sd$,$sd$초급$sd$,$sd$["손바닥으로 어깨만 살짝 터치해요", "가드는 내리지 말고 스텝으로 피해요", "상대의 어깨와 눈을 계속 봐요", "작게 여러 번 움직여 거리를 지켜요"]$sd$::jsonb,$sd$["피하려고 뒤로 크게 도망가요 → 반 발짝씩 작게 움직이며 거리만 살짝 벌려요", "터치에 정신이 팔려 가드가 내려가요 → 한 손은 항상 턱 옆에 남겨 두어요"]$sd$::jsonb,6,180,$sd$/assets/training/shoulder-touch-guard-game.png$sd$),
($sd$컨디셔닝$sd$,$sd$플랭크 버티기$sd$,$sd$팔꿈치와 발끝으로 몸을 판자처럼 곧게 버텨요$sd$,$sd$팔꿈치를 바닥에 대고 몸을 머리부터 발끝까지 판자처럼 곧게 유지하는 코어 운동이에요. 배와 엉덩이에 힘을 주고 20~30초를 버텨요. 30초 쉬면서 3번 반복해요. 튼튼한 코어는 흔들리지 않는 펀치와 가드의 바탕이 돼요. 힘들면 무릎을 바닥에 대고 같은 자세로 버텨도 좋아요.$sd$,$sd$몸의 중심을 잡아 주는 코어가 튼튼해져서 펀치를 던져도 몸이 흔들리지 않게 돼요.$sd$,$sd$배·허리·코어 전체$sd$,$sd$초급$sd$,$sd$["팔꿈치는 어깨 바로 아래에 놓아요", "머리부터 발뒤꿈치까지 일직선을 만들어요", "배꼽을 등 쪽으로 당기며 힘을 줘요", "숨은 멈추지 말고 계속 쉬어요"]$sd$::jsonb,$sd$["엉덩이가 하늘로 솟아요 → 거울을 보며 등과 엉덩이를 한 줄로 낮춰요", "허리가 아래로 축 처져요 → 배에 힘을 더 주고, 힘들면 무릎을 바닥에 대요"]$sd$::jsonb,2,190,$sd$/assets/training/plank-hold.png$sd$),
($sd$컨디셔닝$sd$,$sd$스쿼트 펀치$sd$,$sd$앉았다 일어나면서 앞으로 펀치를 쭉 뻗어요$sd$,$sd$다리 힘과 펀치를 한 번에 기르는 드릴이에요. 가드 자세에서 의자에 앉듯 스쿼트로 내려갔다가, 일어나는 힘을 그대로 이용해 잽과 스트레이트를 한 번씩 뻗어요. 다리에서 올라온 힘이 주먹까지 전해지는 느낌을 배우는 게 핵심이에요. 10회씩 3세트 해요. 힘들면 스쿼트를 얕게 하고 펀치만 천천히 해도 돼요.$sd$,$sd$펀치의 힘이 팔이 아니라 다리에서 나온다는 것을 몸으로 배우고, 하체 힘과 체력이 함께 좋아져요.$sd$,$sd$허벅지·엉덩이·전신 연결 감각$sd$,$sd$초급$sd$,$sd$["엉덩이를 뒤로 빼며 의자에 앉듯 내려가요", "무릎은 발끝과 같은 방향을 봐요", "일어나는 힘으로 원투를 뻗어요", "펀치 후 손은 바로 턱 옆으로 돌아와요"]$sd$::jsonb,$sd$["무릎이 안쪽으로 모여요 → 발끝과 무릎이 같은 곳을 보게 살짝 벌려요", "내려갈 때 뒤꿈치가 들려요 → 발바닥 전체로 바닥을 누르면서 앉아요"]$sd$::jsonb,3,200,$sd$/assets/training/squat-punch.png$sd$),
($sd$컨디셔닝$sd$,$sd$3분 라운드 믹스$sd$,$sd$3분 동안 펀치·스텝·스쿼트를 섞어 쉬지 않고 움직여요$sd$,$sd$실제 경기 한 라운드와 같은 3분을 버티는 체력 드릴이에요. 잽 10회, 스텝 10회, 스쿼트 5회 순서를 3분 동안 계속 반복해요. 빨리 하는 것보다 마지막 1분까지 자세가 무너지지 않는 게 목표예요. 라운드가 끝나면 1분 쉬어요. 힘들면 2분 라운드부터 시작해서 조금씩 늘려요.$sd$,$sd$3분 라운드를 버티는 몸의 리듬과 지구력이 생겨서 라운드 훈련이 두렵지 않게 돼요.$sd$,$sd$심폐 지구력·전신 체력$sd$,$sd$초급$sd$,$sd$["잽 10회, 스텝 10회, 스쿼트 5회 순서를 소리 내어 세요", "지쳐도 가드 높이는 지켜요", "숨은 후후 내쉬며 리듬을 맞춰요", "마지막 30초에 자세를 한 번 더 점검해요"]$sd$::jsonb,$sd$["처음 1분에 전속력을 다 써 버려요 → 3분 내내 같은 속도로 갈 수 있는 빠르기를 골라요", "지치면 가드가 허리까지 내려가요 → 힘들수록 가드를 외치며 턱 옆으로 올려요"]$sd$::jsonb,8,210,$sd$/assets/training/three-minute-round-mix.png$sd$),
($sd$샌드백$sd$,$sd$샌드백 거리 재기 터치$sd$,$sd$샌드백에 잽이 딱 닿는 거리를 발로 찾아내요$sd$,$sd$내 잽이 딱 닿는 거리를 몸으로 배우는 샌드백 연습이에요. 샌드백에서 두 걸음 떨어져 섰다가 스텝으로 들어가, 팔이 쭉 펴진 채 잽이 톡 닿는 곳에서 멈춰요. 가볍게 터치하고 다시 스텝으로 빠져나와요. 세게 치는 연습이 아니라 나만의 거리를 찾는 연습이에요. 10회씩 3세트 해요.$sd$,$sd$내 팔이 닿는 거리를 발이 기억하게 돼서 너무 붙지도, 너무 멀지도 않은 좋은 위치를 잡을 수 있어요.$sd$,$sd$거리 감각·스텝과 잽 연결$sd$,$sd$초급$sd$,$sd$["들어가서 잽이 톡 닿으면 그게 내 거리예요", "팔이 다 펴진 채로 닿는 곳을 찾아요", "터치하자마자 뒷발부터 빠져나와요", "들어갈 때도 나올 때도 가드는 턱 옆이에요"]$sd$::jsonb,$sd$["너무 가까이 붙어 팔이 굽은 채 닿아요 → 반 발짝 물러나 팔이 쭉 펴지는 거리를 다시 찾아요", "터치하고 그 자리에 서 있어요 → 닿자마자 들어간 속도 그대로 빠져나와요"]$sd$::jsonb,3,220,$sd$/assets/training/bag-range-finder-touch.png$sd$),
($sd$샌드백$sd$,$sd$샌드백 원투 리듬$sd$,$sd$샌드백에 하나-둘 박자로 잽과 스트레이트를 이어 쳐요$sd$,$sd$샌드백에 원투를 일정한 박자로 반복하는 연습이에요. 세게 치는 것보다 탁-탁 하는 두 박자가 매번 똑같이 나오는 게 목표예요. 10번 치고 숨을 고른 뒤 다시 10번, 모두 3세트 해요. 원투 사이에 가드가 잠깐이라도 내려오면 안 돼요. 손목이 아프면 치는 세기를 줄이고 폼만 확인해요.$sd$,$sd$원투가 하나의 동작처럼 이어지고, 박자가 일정해지면서 콤비네이션의 기초 리듬이 완성돼요.$sd$,$sd$팔·허리 회전·콤비 리듬$sd$,$sd$초급$sd$,$sd$["탁-탁 두 박자를 매번 똑같이 유지해요", "잽 친 손이 돌아오면서 스트레이트가 나가요", "허리를 살짝 돌려 뒷손에 힘을 실어요", "10회마다 멈춰서 스탠스를 다시 잡아요"]$sd$::jsonb,$sd$["세게 치려다 박자가 엉켜요 → 힘을 반으로 줄이고 박자부터 똑같이 맞춰요", "스트레이트를 칠 때 턱이 들려요 → 턱을 당기고 어깨 뒤에 숨기듯 쳐요"]$sd$::jsonb,4,230,$sd$/assets/training/bag-one-two-rhythm.png$sd$),
($sd$미트$sd$,$sd$미트 잽 타깃 맞히기$sd$,$sd$코치가 든 미트 한가운데를 잽으로 정확히 맞혀요$sd$,$sd$코치가 든 미트의 한가운데를 잽으로 맞히는 정확도 연습이에요. 코치가 미트를 눈높이로 들어 보이면 스텝으로 거리를 맞추고 잽을 뻗어 팡 소리가 나게 맞혀요. 코치가 미트 위치를 조금씩 바꾸니까 발로 따라가면서 쳐요. 10회 중 몇 번이나 한가운데를 맞혔는지 세어 봐요.$sd$,$sd$움직이는 목표를 발로 따라가 정확히 맞히는 능력이 생겨요. 미트 훈련의 첫 단추예요.$sd$,$sd$조준 정확도·스텝과 잽 연결$sd$,$sd$초급$sd$,$sd$["미트 한가운데 점을 보고 쳐요", "발로 거리를 맞춘 다음에 잽을 뻗어요", "팡 소리가 나면 잘 맞은 거예요", "친 손은 바로 턱 옆으로 돌아와요"]$sd$::jsonb,$sd$["미트가 움직이면 팔만 길게 뻗어 쫓아가요 → 먼저 스텝으로 거리를 맞춘 뒤에 쳐요", "맞히고 나서 그대로 구경해요 → 치자마자 가드로 돌아와 다음 잽을 준비해요"]$sd$::jsonb,4,240,$sd$/assets/training/mitt-jab-target.png$sd$),
($sd$쿨다운$sd$,$sd$정리 스트레칭 루틴$sd$,$sd$운동이 끝나면 몸을 천천히 늘리며 마무리해요$sd$,$sd$훈련 마지막에 하는 마무리 스트레칭이에요. 어깨 늘리기, 팔 교차로 당기기, 허벅지 앞뒤 늘리기, 종아리 늘리기를 한 자세당 20초씩 해요. 반동 없이 지그시 늘리고 숨을 천천히 내쉬면서 해요. 오늘 가장 많이 쓴 어깨와 다리는 꼭 챙겨서 늘려 줘요.$sd$,$sd$훈련으로 뭉친 근육이 부드럽게 풀려서 다음 훈련 때 몸이 한결 가볍게 움직여요.$sd$,$sd$어깨·허벅지·종아리 전신$sd$,$sd$초급$sd$,$sd$["한 자세를 20초씩 지그시 유지해요", "반동 주지 말고 천천히 늘려요", "숨을 길게 내쉬며 몸에 힘을 빼요", "아픈 느낌 직전, 시원한 만큼만 늘려요"]$sd$::jsonb,$sd$["아플 때까지 세게 당겨요 → 시원하다 싶은 곳에서 멈추고 호흡으로 20초를 채워요", "스트레칭을 건너뛰고 바로 집에 가요 → 딱 3분만 투자해서 내일의 몸을 지켜요"]$sd$::jsonb,1,250,$sd$/assets/training/cooldown-stretch-routine.png$sd$),
($sd$쿨다운$sd$,$sd$박스 호흡 정리$sd$,$sd$네 박자에 맞춰 숨을 천천히 쉬며 심장을 진정시켜요$sd$,$sd$훈련으로 빨라진 심장과 호흡을 가라앉히는 마무리 호흡법이에요. 편하게 서거나 앉아서 코로 4초 마시고, 4초 멈추고, 입으로 4초 내쉬고, 4초 쉬어요. 네모를 그리듯 이 네 박자를 5번 반복해요. 어깨가 내려가고 숨이 편해지면 오늘 훈련은 잘 마무리된 거예요.$sd$,$sd$훈련 후 몸과 마음을 차분하게 정리하는 방법을 배워요. 라운드 사이에 숨을 고르는 연습도 돼요.$sd$,$sd$호흡·마음 진정$sd$,$sd$초급$sd$,$sd$["코로 4초 동안 천천히 들이마셔요", "4초 멈췄다가 입으로 4초 내쉬어요", "내쉴 때 어깨를 아래로 툭 떨어뜨려요", "마음속으로 숫자를 세며 5번 반복해요"]$sd$::jsonb,$sd$["숨을 크게 몰아쉬며 서둘러요 → 숫자 4를 천천히 세면서 박자를 지켜요", "어깨와 목에 힘이 남아 있어요 → 내쉴 때마다 어깨를 한 번씩 내려놓아요"]$sd$::jsonb,1,260,$sd$/assets/training/box-breathing-cooldown.png$sd$),
($sd$콤비네이션$sd$,$sd$더블 잽 원투 (1-1-2)$sd$,$sd$잽을 두 번 톡톡 치고 바로 뒷손 스트레이트를 치는 3연타예요.$sd$,$sd$같은 앞손으로 잽을 두 번 연속으로 치고, 상대가 가드를 올리는 순간 뒷손 스트레이트로 마무리하는 콤비네이션입니다. 첫 잽은 거리 재기, 둘째 잽은 시야 가리기, 스트레이트는 결정타 역할을 합니다. 두 잽 사이에 발이 멈추지 않도록 작은 전진 스텝으로 리듬을 이어 주세요. 마지막 스트레이트 후에는 반드시 가드로 돌아옵니다.$sd$,$sd$앞손 연타 스피드와 원투 연결 감각이 좋아지고, 콤비네이션의 기본 리듬이 몸에 붙습니다.$sd$,$sd$앞손 스피드, 어깨, 리듬감, 거리 감각$sd$,$sd$초급$sd$,$sd$["잽 두 번은 가볍고 빠르게, 힘은 마지막 2에", "잽 사이에도 뒷손 가드는 턱 옆에", "스트레이트 때 뒷발 회전과 힙을 같이", "치고 나면 바로 가드 복귀"]$sd$::jsonb,$sd$["첫 잽에 힘을 다 실어 둘째 잽이 느려짐 → 잽은 툭툭 가볍게, 힘은 마지막에만", "잽 두 번 치는 동안 제자리에 멈춤 → 작은 전진 스텝과 함께 치기", "스트레이트 후 손이 아래로 떨어짐 → 친 손이 먼저 턱으로 복귀"]$sd$::jsonb,11,100,$sd$/assets/training/double-jab-cross.png$sd$),
($sd$콤비네이션$sd$,$sd$잽-리드훅 콤비 (1-3)$sd$,$sd$앞손으로 잽을 치고 같은 손으로 바로 옆에서 도는 훅을 치는 연습이에요.$sd$,$sd$잽을 뻗은 앞손을 거둬들이면서 그대로 같은 손으로 리드훅을 연결하는 콤비네이션입니다. 직선 공격 뒤에 곡선 공격이 이어져 상대가 예측하기 어려운 조합입니다. 잽이 돌아오는 힘을 훅의 회전으로 자연스럽게 바꾸는 것이 핵심입니다. 훅을 칠 때는 팔꿈치를 어깨 높이까지 들고 앞발 끝과 무릎, 힙이 함께 돌아야 합니다.$sd$,$sd$같은 손으로 이어 치는 연결 기술이 늘고, 직선에서 곡선으로 바꾸는 공격 전환 감각을 익힙니다.$sd$,$sd$앞손 연결 능력, 몸통 회전, 코어$sd$,$sd$초급$sd$,$sd$["잽은 직선, 훅은 옆에서 도는 곡선", "훅 때 팔꿈치는 어깨 높이까지", "앞발 끝을 안쪽으로 돌리며 힙 회전", "반대 손 가드는 턱에 고정"]$sd$::jsonb,$sd$["훅이 크게 돌아 나감 → 팔꿈치 각도 90도로 콤팩트하게 접기", "팔 힘으로만 훅을 침 → 발끝-무릎-힙 회전에서 힘 가져오기"]$sd$::jsonb,11,110,$sd$/assets/training/jab-lead-hook-combo.png$sd$),
($sd$콤비네이션$sd$,$sd$원투쓰리 콤비 (1-2-3)$sd$,$sd$잽, 스트레이트, 훅을 물 흐르듯 세 번 이어 치는 기본 3연타예요.$sd$,$sd$잽(1), 스트레이트(2), 리드훅(3)을 끊김 없이 이어 치는 복싱의 대표 3연타 콤비네이션입니다. 스트레이트를 칠 때 몸이 앞으로 돌면서 생긴 회전을 그대로 되돌리며 리드훅에 사용합니다. 리듬은 '탁-탁-탕'으로, 마지막 훅에 가장 큰 힘이 실리게 합니다. 세 번을 다 친 후 가드 복귀까지가 한 세트입니다.$sd$,$sd$좌우 회전을 주고받는 콤비네이션 리듬의 뼈대가 만들어지고, 블루 리그 콤비의 기준 동작이 됩니다.$sd$,$sd$전신 회전 연결, 리듬감, 밸런스$sd$,$sd$초급$sd$,$sd$["1-2는 직선, 3은 회전으로 마무리", "2에서 돌아간 힙을 3에서 되돌리기", "리듬은 탁-탁-탕", "세 번 치는 동안 머리 높이 일정하게"]$sd$::jsonb,$sd$["2와 3 사이가 뚝 끊김 → 2의 회전 반동을 그대로 3으로 잇기", "훅 칠 때 몸이 앞으로 쏠림 → 체중은 두 발 사이 중앙 유지", "마지막에 가드를 안 올림 → 훅 친 손을 턱으로 복귀"]$sd$::jsonb,12,120,$sd$/assets/training/one-two-three-combo.png$sd$),
($sd$샌드백$sd$,$sd$샌드백 3연타 정타 드릴$sd$,$sd$샌드백 한 곳을 정해서 1-2-3를 정확히 같은 자리에 맞히는 연습이에요.$sd$,$sd$샌드백에 눈높이 목표 지점을 하나 정하고, 1-2-3 콤비를 그 지점에 정확히 맞히는 반복 훈련입니다. 세게 치는 것보다 세 발이 모두 같은 지점에 정타로 꽂히는 것이 목표입니다. 10회 연속 성공을 한 세트로 하고, 흔들리는 샌드백에 맞춰 스텝으로 거리를 다시 잡는 연습도 함께 합니다. 손목이 꺾이지 않도록 주먹 면을 똑바로 세워서 맞힙니다.$sd$,$sd$펀치 정확도와 거리 조절 능력이 좋아지고, 주먹과 손목의 정렬이 안정됩니다.$sd$,$sd$정확도, 손목 정렬, 거리 감각$sd$,$sd$초급$sd$,$sd$["목표 지점에서 눈을 떼지 않기", "세게보다 정확하게", "백이 흔들리면 스텝으로 거리부터 다시 잡기", "주먹 앞면으로 평평하게 맞히기"]$sd$::jsonb,$sd$["백이 움직이면 팔만 뻗어 쫓아감 → 발로 거리를 먼저 맞춘 뒤 치기", "힘 자랑하다 폼이 무너짐 → 속도를 60%로 낮춰 정타부터"]$sd$::jsonb,12,130,$sd$/assets/training/heavybag-triple-accuracy.png$sd$),
($sd$컨디셔닝$sd$,$sd$인터벌 섀도$sd$,$sd$30초는 아주 빠르게, 30초는 살살, 속도를 바꿔 가며 하는 섀도복싱이에요.$sd$,$sd$30초 전력 콤비네이션과 30초 가벼운 스텝·잽을 번갈아 반복하는 리듬 컨디셔닝 훈련입니다. 빠른 구간에서는 배운 콤비를 최대 속도로 치고, 느린 구간에서는 호흡을 고르며 폼을 점검합니다. 3분을 한 라운드로 총 2~3라운드 진행합니다. 힘들면 전력 구간을 20초로 줄이고 회복 구간을 40초로 늘려도 좋습니다.$sd$,$sd$라운드 내내 속도를 바꿔도 무너지지 않는 체력과 스스로 페이스를 조절하는 능력이 생깁니다.$sd$,$sd$심폐 체력, 페이스 조절, 콤비 지속력$sd$,$sd$중급$sd$,$sd$["빠른 구간에도 폼은 그대로 유지", "느린 구간엔 코로 길게 호흡", "타이머 소리에 즉시 속도 전환", "어깨에 힘 빼고 가볍게"]$sd$::jsonb,$sd$["빠른 구간에 팔만 마구 휘두름 → 배운 콤비 그대로 속도만 올리기", "느린 구간에 완전히 멈춰 버림 → 바운스와 가벼운 잽은 계속"]$sd$::jsonb,12,140,$sd$/assets/training/interval-shadow-boxing.png$sd$),
($sd$콤비네이션$sd$,$sd$잽-리어어퍼 콤비 (1-6)$sd$,$sd$잽으로 길을 열고 뒷손으로 아래에서 위로 퍼 올리는 어퍼컷을 치는 연습이에요.$sd$,$sd$잽으로 상대의 시선을 위로 끌어올린 뒤, 뒷손 어퍼컷(6)을 아래에서 위로 연결하는 콤비네이션입니다. 어퍼컷은 무릎을 살짝 굽혔다 펴는 힘과 힙 회전으로 쳐야 하며 팔로만 퍼 올리면 안 됩니다. 주먹은 손바닥이 내 쪽을 보게 돌려서 턱 높이까지만 콤팩트하게 올립니다. 어퍼컷 후 상체가 뒤로 젖혀지지 않게 곧게 유지합니다.$sd$,$sd$직선 공격과 위로 올리는 공격을 잇는 감각을 익히고, 하체에서 힙으로 이어지는 힘 전달이 좋아집니다.$sd$,$sd$하체·힙 연결, 뒷손 어퍼 감각, 코어$sd$,$sd$초급$sd$,$sd$["잽으로 시선은 위로, 어퍼는 아래에서 시작", "무릎을 굽혔다 펴는 힘으로 치기", "어퍼는 턱 높이까지만 짧게", "상체는 꼿꼿이, 뒤로 젖히지 않기"]$sd$::jsonb,$sd$["팔로만 크게 퍼 올림 → 무릎과 힙에서 시작해 짧게 올리기", "어퍼 칠 때 몸이 뒤로 젖혀짐 → 배에 힘 주고 상체 수직 유지"]$sd$::jsonb,13,150,$sd$/assets/training/jab-rear-uppercut.png$sd$),
($sd$콤비네이션$sd$,$sd$바디-헤드 콤비 (몸통-얼굴)$sd$,$sd$몸통을 먼저 치고 상대 가드가 내려오면 바로 얼굴 쪽을 치는 연습이에요.$sd$,$sd$스트레이트를 몸통 높이로 낮게 친 뒤, 이어서 리드훅을 얼굴 높이로 연결하는 상하 콤비네이션입니다. 몸통을 칠 때는 무릎을 굽혀 몸 전체를 낮추고, 팔만 내려서 치지 않습니다. 낮았다가 일어나는 힘을 그대로 훅의 회전으로 연결하는 것이 포인트입니다. 섀도로 폼을 익힌 뒤 샌드백에서 높이를 바꿔 가며 반복합니다.$sd$,$sd$공격 높이를 위아래로 바꾸는 능력이 생기고, 하체 힘을 펀치에 싣는 습관이 자랍니다.$sd$,$sd$높이 전환 능력, 하체, 코어$sd$,$sd$중급$sd$,$sd$["몸통 칠 땐 무릎을 굽혀 같이 내려가기", "시선은 계속 목표 쪽에 두기", "일어나는 힘으로 훅을 연결", "낮은 자세에서도 가드 유지"]$sd$::jsonb,$sd$["허리만 숙여 몸통을 침 → 무릎을 굽혀 몸을 수직으로 낮추기", "바디 친 뒤 일어나며 멈칫함 → 일어나는 반동을 훅에 바로 싣기"]$sd$::jsonb,13,160,$sd$/assets/training/body-head-combo.png$sd$),
($sd$콤비네이션$sd$,$sd$4연타 콤비 (1-2-3-2)$sd$,$sd$잽-스트레이트-훅-스트레이트, 네 번을 쉬지 않고 이어 치는 연습이에요.$sd$,$sd$1-2-3 콤비 뒤에 스트레이트(2)를 한 번 더 붙여 네 번을 연속으로 치는 블루 리그 대표 콤비네이션입니다. 몸이 좌우로 번갈아 회전하기 때문에 리듬이 끊기면 바로 티가 납니다. 처음에는 천천히 정확하게 치고, 익숙해지면 마지막 2까지 속도를 올립니다. 네 번 치는 동안 발 위치와 머리 높이가 흔들리지 않아야 합니다.$sd$,$sd$긴 콤비네이션에서도 밸런스와 리듬을 끝까지 유지하는 연타 지속력이 생깁니다.$sd$,$sd$연타 지속력, 좌우 회전 리듬, 밸런스$sd$,$sd$중급$sd$,$sd$["몸 회전을 좌-우-좌-우로 번갈아", "리듬 먼저, 속도는 나중에", "네 발 모두 친 뒤 가드 복귀까지 한 세트", "발끝만 돌리고 발 위치는 고정"]$sd$::jsonb,$sd$["3에서 마지막 2로 갈 때 멈칫함 → 훅의 회전을 되감으며 바로 2 연결", "연타 중 발이 폴짝 뜀 → 발바닥을 바닥에 가볍게 붙이고 회전만", "뒤로 갈수록 펀치가 짧아짐 → 마지막 2도 힙 회전 끝까지"]$sd$::jsonb,14,170,$sd$/assets/training/four-punch-combo.png$sd$),
($sd$미트$sd$,$sd$미트 4연타 드릴 (1-2-3-2)$sd$,$sd$코치 미트에 네 번 콤비를 정확한 순서와 소리로 맞히는 연습이에요.$sd$,$sd$코치가 들어 주는 미트에 1-2-3-2 콤비를 정확한 순서·높이·타이밍으로 맞히는 훈련입니다. 미트가 '팡' 하고 울리는 정타 소리가 나야 한 번으로 인정합니다. 코치의 미트 위치가 바뀌면 스텝으로 거리를 조절한 뒤 콤비를 시작합니다. 10세트를 기본으로 하되, 힘들면 세트 사이 휴식을 늘리고 속도를 낮춰도 됩니다.$sd$,$sd$실제 목표물에 콤비를 맞히는 타이밍과 정확도가 자라고, 정타 감각이 손에 익습니다.$sd$,$sd$정확도, 타이밍, 거리 조절$sd$,$sd$중급$sd$,$sd$["미트 중앙을 끝까지 보고 치기", "정타 소리 '팡'이 나게", "미트가 이동하면 발부터 따라가기", "콤비 후 가드 올리고 반 스텝 아웃"]$sd$::jsonb,$sd$["미트를 밀어서 침 → 스냅 있게 치고 바로 회수하기", "마음이 급해져 3을 건너뜀 → 입으로 1-2-3-2를 세며 치기"]$sd$::jsonb,14,180,$sd$/assets/training/focus-mitt-four-punch.png$sd$),
($sd$방어$sd$,$sd$슬립 카운터 입문 (슬립-2)$sd$,$sd$상대 잽을 옆으로 살짝 피하고 그 자리에서 바로 스트레이트로 되받아치는 연습이에요.$sd$,$sd$바깥쪽으로 슬립해 상대의 잽을 흘려보낸 뒤, 피하면서 만들어진 몸의 꼬임을 그대로 스트레이트(2)로 되돌려 치는 카운터 입문 훈련입니다. 피하기와 반격이 따로따로가 아니라 하나의 동작처럼 이어져야 합니다. 처음에는 거울 앞에서, 다음에는 코치가 미트나 패드로 천천히 보내 주는 잽 신호에 맞춰 연습합니다. 슬립 폭은 머리 하나만큼만 작게, 시선은 항상 앞을 유지합니다.$sd$,$sd$방어에서 공격으로 넘어가는 첫 연결 고리가 생기고, 카운터의 감각이 열립니다.$sd$,$sd$상체 회피, 카운터 타이밍, 코어 회전$sd$,$sd$초급$sd$,$sd$["슬립은 머리 하나 폭만큼만 작게", "피하며 감긴 몸을 풀면서 2", "시선은 계속 정면에", "슬립 중에도 두 손 가드 유지"]$sd$::jsonb,$sd$["크게 피해서 반격이 늦어짐 → 최소한만 피하고 바로 되치기", "슬립할 때 눈이 바닥을 봄 → 턱만 당기고 시선은 목표에 고정"]$sd$::jsonb,15,190,$sd$/assets/training/slip-counter-straight.png$sd$),
($sd$방어$sd$,$sd$패리-리턴 드릴$sd$,$sd$상대 잽을 손바닥으로 톡 쳐내고 곧바로 내 잽으로 돌려주는 연습이에요.$sd$,$sd$뒷손 손바닥으로 상대의 잽을 살짝 쳐내는 패리 직후, 앞손 잽으로 즉시 반격하는 훈련입니다. 패리는 크게 휘두르지 않고 손목 스냅으로 10cm 정도만 걷어냅니다. 쳐내는 손과 반격하는 손이 거의 동시에 움직일 만큼 간격을 좁히는 것이 목표입니다. 코치가 미트를 낀 손으로 천천히 뻗어 주는 잽 신호에 맞춰 비접촉으로 반복합니다.$sd$,$sd$막기만 하던 방어가 즉시 반격으로 이어지고, 손 반응 속도가 빨라집니다.$sd$,$sd$반응 속도, 양손 협응, 방어-공격 전환$sd$,$sd$초급$sd$,$sd$["패리는 10cm만 작게", "쳐냄과 동시에 앞손 출발 준비", "패리한 손은 바로 턱으로 복귀", "상대 어깨 움직임을 보고 미리 읽기"]$sd$::jsonb,$sd$["패리를 크게 휘두름 → 손목 스냅으로 짧게 걷어내기", "패리 후 한 박자 쉬고 반격 → '쳐냄=반격 시작'으로 붙이기"]$sd$::jsonb,16,200,$sd$/assets/training/parry-return-jab.png$sd$),
($sd$방어$sd$,$sd$위빙-훅 연결$sd$,$sd$상대 훅을 U자로 피해 지나간 다음 바로 내 훅으로 이어 치는 연습이에요.$sd$,$sd$상대 훅의 궤도 아래로 U자를 그리며 위빙한 뒤, 올라오면서 리드훅으로 반격하는 훈련입니다. 위빙은 허리를 숙이는 것이 아니라 무릎을 굽혀 몸 전체가 U자로 이동해야 합니다. 올라오는 힘과 힙 회전을 합쳐서 훅에 싣는 것이 핵심입니다. 코치가 미트로 천천히 그려 주는 훅 궤도나 로프 아래를 지나는 방식으로 안전하게 반복합니다.$sd$,$sd$회피와 반격을 한 동작으로 잇는 능력이 생기고, 하체 힘이 크게 좋아집니다.$sd$,$sd$하체, 회피-반격 전환, 몸통 회전$sd$,$sd$중급$sd$,$sd$["무릎으로 내려가고 무릎으로 올라오기", "U자 바닥에서 멈추지 않기", "올라오는 힘을 훅에 그대로 싣기", "위빙 내내 가드와 시선 유지"]$sd$::jsonb,$sd$["허리만 숙여 머리가 뚝 떨어짐 → 무릎을 굽히고 상체는 세우기", "위빙 후 일어나서 한 박자 쉼 → 올라오는 동작과 훅을 하나로"]$sd$::jsonb,16,210,$sd$/assets/training/weave-hook-counter.png$sd$),
($sd$방어$sd$,$sd$디펜스-카운터 체인$sd$,$sd$피하고 치고, 또 피하고 치고를 연속으로 이어 가는 종합 방어 연습이에요.$sd$,$sd$슬립 후 스트레이트, 위빙 후 훅처럼 배운 방어-반격 세트를 두세 개 연속으로 이어 가는 종합 훈련입니다. 코치가 '잽', '훅' 하고 신호를 주면 그에 맞는 회피와 카운터를 즉시 골라 수행합니다. 정해진 순서를 외워서 하는 단계부터 시작해, 익숙해지면 무작위 신호로 넘어갑니다. 한 반격이 끝날 때마다 가드와 스탠스를 완전히 회복한 뒤 다음 신호를 받습니다.$sd$,$sd$방어 기술을 상황에 맞게 고르는 판단력과 끊기지 않는 연속 대응 능력이 생깁니다.$sd$,$sd$판단 속도, 방어-공격 전환, 집중력$sd$,$sd$중급$sd$,$sd$["신호를 들으면 생각보다 몸이 먼저", "잽 신호엔 슬립-2, 훅 신호엔 위빙-3", "카운터 후 스탠스 완전 복구", "서두르지 말고 하나씩 정확히"]$sd$::jsonb,$sd$["신호마다 같은 방어만 반복 → 잽/훅 신호별 대응을 구분해 연습", "카운터 후 자세가 흐트러진 채 다음 동작 → 가드 복구 확인 후 진행"]$sd$::jsonb,17,220,$sd$/assets/training/defense-counter-chain.png$sd$),
($sd$미트$sd$,$sd$콜아웃 미트 드릴$sd$,$sd$코치가 부르는 번호를 듣자마자 바로 그 콤비를 미트에 치는 연습이에요.$sd$,$sd$코치가 '원투', '원투쓰리'처럼 콤비 번호를 외치면 듣는 즉시 해당 콤비를 미트에 정확히 치는 반응 훈련입니다. 미리 순서를 알 수 없기 때문에 진짜 반응 속도와 콤비 암기력이 시험됩니다. 정타 소리와 올바른 순서가 모두 맞아야 성공으로 칩니다. 3분 라운드로 진행하며, 힘들면 콜 간격을 넓혀 달라고 요청해 페이스를 조절합니다.$sd$,$sd$듣고 바로 몸이 나가는 실전형 반응력이 생기고, 배운 콤비의 완성도가 올라갑니다.$sd$,$sd$반응 속도, 콤비 암기, 집중력$sd$,$sd$중급$sd$,$sd$["콜을 듣고 반 박자 안에 첫 펀치", "헷갈리면 멈추지 말고 원투라도 치기", "매 콤비 후 가드와 스텝 리셋", "정타 소리로 스스로 확인"]$sd$::jsonb,$sd$["콜을 듣고 머리로 생각하다 늦어짐 → 자주 나오는 콜부터 몸으로 외우기", "빨리 치려다 순서가 뒤섞임 → 속도를 낮추고 순서 정확도부터"]$sd$::jsonb,18,230,$sd$/assets/training/callout-mitt-drill.png$sd$),
($sd$샌드백$sd$,$sd$샌드백 타깃 마크 드릴$sd$,$sd$샌드백에 붙인 테이프 표시만 골라서 정확히 맞히는 연습이에요.$sd$,$sd$샌드백의 얼굴 높이와 몸통 높이 두 곳에 테이프로 표시를 붙이고, 지정된 콤비를 표시 지점에만 정확히 맞히는 정확도 훈련입니다. 예를 들어 1-2는 위 표시, 3은 아래 표시처럼 높이를 섞어 목표를 바꿉니다. 10회 중 몇 번이 정타였는지 세어 기록하고 지난 기록과 비교합니다. 흔들리는 백을 스텝으로 따라가며 치는 것까지가 과제입니다.$sd$,$sd$높이가 다른 목표를 구분해 정확히 맞히는 조준 능력이 자라고, 기록 비교로 성장이 보입니다.$sd$,$sd$정밀 조준, 높이 전환, 거리 유지$sd$,$sd$중급$sd$,$sd$["칠 표시를 먼저 눈으로 찍고 치기", "위-아래 전환은 무릎으로", "10회 중 정타 개수 세기", "백의 반동은 스텝으로 받기"]$sd$::jsonb,$sd$["표시 근처에 대충 맞힘 → 속도를 줄여 표시 정중앙 조준", "아래 표시를 팔만 내려서 침 → 무릎을 굽혀 몸 전체로 낮추기"]$sd$::jsonb,18,240,$sd$/assets/training/heavybag-target-mark.png$sd$),
($sd$풋워크$sd$,$sd$피벗 콤비 드릴$sd$,$sd$몸을 문처럼 빙글 돌려 옆으로 각도를 바꾼 다음 바로 콤비를 치는 연습이에요.$sd$,$sd$앞발을 축으로 몸을 45~90도 회전하는 피벗으로 각도를 바꾼 뒤, 새 각도에서 즉시 1-2 콤비를 치는 훈련입니다. 정면에서만 치던 공격을 옆 각도에서 치게 되어, 상대가 따라오기 어려운 위치를 만드는 연습입니다. 피벗이 끝나는 순간 이미 스탠스가 완성되어 있어야 콤비가 바로 나갑니다. 좌우 양방향을 모두 연습합니다.$sd$,$sd$정면 승부에서 벗어나 각도를 만들어 치는 한 단계 위의 움직임을 익힙니다.$sd$,$sd$피벗 정확도, 각도 감각, 밸런스$sd$,$sd$중급$sd$,$sd$["앞발이 축, 뒷발이 컴퍼스처럼 회전", "피벗 끝나면 스탠스도 완성", "돌자마자 1-2", "회전 중 머리 높이 일정하게"]$sd$::jsonb,$sd$["피벗 후 발이 좁아져 휘청임 → 돌고 나서 어깨너비인지 확인", "돌면서 가드가 내려감 → 회전 내내 두 손을 턱 옆에"]$sd$::jsonb,19,250,$sd$/assets/training/pivot-combo-drill.png$sd$),
($sd$풋워크$sd$,$sd$인앤아웃 콤비 스텝$sd$,$sd$빠르게 들어가서 콤비를 치고 재빨리 뒤로 빠져나오는 연습이에요.$sd$,$sd$닿지 않는 거리에서 스텝인으로 순간 진입해 1-2-3 콤비를 치고, 즉시 스텝아웃으로 안전거리까지 빠져나오는 훈련입니다. 들어갈 때는 앞발부터, 나올 때는 뒷발부터 미는 것이 기본입니다. 치는 것보다 빠져나오기가 늦지 않는 것이 이 드릴의 진짜 목표입니다. 샌드백이나 미트 앞에서 진입-콤비-이탈을 한 세트로 반복합니다.$sd$,$sd$치고 빠지는 타이밍이 몸에 배어, 안전한 거리에서 공격을 시작하고 끝내는 습관이 생깁니다.$sd$,$sd$순간 스피드, 거리 전환, 하체$sd$,$sd$중급$sd$,$sd$["들어갈 땐 앞발, 나올 땐 뒷발부터", "마지막 펀치와 동시에 이탈 시작", "나온 뒤에도 가드와 스탠스 유지", "진입은 반 발짝만 깊게"]$sd$::jsonb,$sd$["콤비를 다 치고 그 자리에 머무름 → 마지막 펀치에 이탈을 붙이기", "뒤로만 일자로 빠짐 → 가끔 비스듬히 각도를 주며 이탈"]$sd$::jsonb,19,260,$sd$/assets/training/in-and-out-combo-step.png$sd$),
($sd$컨디셔닝$sd$,$sd$블루 마스터 리허설 라운드$sd$,$sd$블루에서 배운 콤비, 피하기, 스텝을 모두 섞어 3분 동안 해 보는 총정리예요.$sd$,$sd$블루 리그에서 배운 콤비네이션, 슬립·위빙 카운터, 피벗과 인앤아웃을 한 라운드 안에 모두 담아 수행하는 종합 리허설입니다. 3분 동안 콤비, 방어-카운터, 각도 이동의 흐름을 스스로 구성해 쉬지 않고 이어 갑니다. 기술 시연 전 최종 점검 단계로, 흐트러진 동작은 코치가 체크해 알려 줍니다. 힘들면 2분 라운드로 줄이고 회복 시간을 충분히 가져도 좋습니다.$sd$,$sd$따로 배운 기술이 하나의 흐름으로 연결되고, 블루 마무리 기술 테스트 준비가 완성됩니다.$sd$,$sd$기술 종합 연결, 라운드 체력, 자기 구성력$sd$,$sd$중급$sd$,$sd$["콤비-방어-이동 순서로 흐름 설계", "빈 시간엔 잽과 바운스로 채우기", "폼이 무너지면 속도를 줄여 폼 우선", "마지막 10초는 전력으로 마무리"]$sd$::jsonb,$sd$["잘하는 콤비만 반복함 → 방어와 풋워크를 최소 1회씩 끼워 넣기", "초반에 전력을 다해 후반 방전 → 3분을 3등분해 페이스 배분"]$sd$::jsonb,20,270,$sd$/assets/training/blue-master-rehearsal.png$sd$),
($sd$쿨다운$sd$,$sd$복서 쿨다운 스트레칭$sd$,$sd$운동 끝나고 어깨, 손목, 허리를 천천히 늘려 주는 마무리 체조예요.$sd$,$sd$훈련 후 많이 쓴 어깨·팔·손목·허리를 천천히 늘려 주는 마무리 스트레칭입니다. 어깨 크로스 스트레칭, 손목 돌리기와 젖히기, 몸통 옆으로 늘리기를 각 20~30초씩 진행합니다. 반동을 주지 않고 숨을 내쉬면서 부드럽게 늘리는 것이 포인트입니다. 훈련으로 올라간 호흡을 차분히 가라앉히며 마칩니다.$sd$,$sd$훈련 후 몸의 긴장을 풀어 주고, 다음 훈련을 가벼운 몸으로 시작하도록 돕습니다.$sd$,$sd$어깨·손목·몸통 유연성, 회복$sd$,$sd$초급$sd$,$sd$["한 동작 20~30초 천천히", "반동 없이 숨을 내쉬며 늘리기", "아픈 지점 직전까지만", "어깨-손목-허리 순서로"]$sd$::jsonb,$sd$["빨리 끝내려고 반동을 줌 → 시간을 정해 두고 지그시 유지", "숨을 참고 버팀 → 내쉬는 숨에 맞춰 조금씩 깊게"]$sd$::jsonb,11,280,$sd$/assets/training/boxer-cooldown-stretch.png$sd$),
($sd$쿨다운$sd$,$sd$호흡 리커버리 워크$sd$,$sd$천천히 걸으면서 코로 숨을 길게 쉬어 두근거리는 심장을 가라앉히는 마무리예요.$sd$,$sd$라운드 훈련 직후 체육관을 천천히 걸으며 호흡을 회복하는 마무리 과정입니다. 코로 4초 마시고 입으로 6초 길게 내쉬는 호흡을 걸음에 맞춰 2~3분 반복합니다. 어깨를 들썩이지 않고 배로 숨 쉬는 복식 호흡을 함께 연습합니다. 호흡이 차분해지면 가벼운 목·어깨 돌리기로 마칩니다.$sd$,$sd$라운드 사이와 훈련 후에 빠르게 호흡을 고르는 회복 습관이 생깁니다.$sd$,$sd$호흡 조절, 회복 습관$sd$,$sd$초급$sd$,$sd$["코로 4초 마시고 입으로 6초 내쉬기", "걸음은 아주 천천히", "어깨 말고 배로 호흡", "허리를 펴고 시선은 정면"]$sd$::jsonb,$sd$["멈춰 서서 허리를 숙이고 헐떡임 → 천천히 걸으며 상체 세우기", "숨을 급하게 몰아쉼 → 내쉬는 숨을 마시는 숨보다 길게"]$sd$::jsonb,15,290,$sd$/assets/training/breathing-recovery-walk.png$sd$);